// Real naturally aged native extraction, visible UI and Flash cross-session read.
// The seed must have been generated by an earlier actual user/Flash turn.
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {ready,prompt} from './skills_mcp_helpers.mjs';
assert.equal(process.env.CODEX_CONFIRM_LIVE_MODEL_TEST,'1');
const out=process.env.REPORT_DIR,seed=process.env.CODEX_EXPECTED_MEMORY_THREAD;
assert(out&&seed);fs.mkdirSync(out,{recursive:true});
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE||'playwright');
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_BIN,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:1440,height:1000}}),checks=[],errors=[];
page.on('pageerror',error=>errors.push(error.message));
const api=value=>page.evaluate(value=>databaseApi('result',{nativeMemory:value}),value);
try{
 await page.goto(process.env.CODEX_WEB_URL);await ready(page);const home=await page.evaluate(()=>state.runtimeInfo.codexHome);assert(home.startsWith('/tmp/'));assert(!fs.existsSync(path.join(home,'auth.json')));
 const records=await api({operation:'summary_search',limit:20});assert(records.records.some(row=>row.threadId===seed));
 const summary=await api({operation:'summary_read',threadId:seed});assert(summary.text.length>50);assert(/中文|Chinese/.test(summary.text));assert(/结论|conclusion/i.test(summary.text));
 await page.locator('[data-view=settings]').click();await page.getByRole('button',{name:'查看与编辑记忆',exact:true}).click();
 const dialog=page.locator('.analysis-memory-dialog');await dialog.locator('.analysis-native-history > summary').click();await dialog.locator('.analysis-native-history').getByRole('button',{name:'查看全文',exact:true}).first().click();
 await page.waitForFunction(()=>document.querySelector('.analysis-native-history .analysis-memory-preview')?.textContent.length>50,null,{timeout:30000});assert((await dialog.locator('.analysis-native-history .analysis-memory-preview').innerText()).length>50);await dialog.screenshot({path:out+'/native-history-visible.png'});await dialog.getByRole('button',{name:'关闭',exact:true}).click();checks.push({name:'服务重启后仍能从设置页面读取真实原生历史提取',passed:true,threadId:seed,sourceUpdatedAt:summary.sourceUpdatedAt,sha256:summary.sha256});
 await page.locator('#new-chat').click();const result=await prompt(page,'请查阅已经保存的历史总结，先用read_analysis_memory读取thread_id为 '+seed+' 的原生任务总结，再用中文简短说明我之前要求以后报告采用什么语言，以及结论和数据依据的顺序。不要新增笔记、查询数据库或编造数字，也不要在正文中重复会话编号。',true,240000);
 assert.equal(result.settings.model,'deepseek-flash');assert.equal(result.settings.modelProvider,'deepseek');
 assert(result.items.some(item=>item.tool==='read_analysis_memory'&&item.status==='completed'&&item.arguments.thread_id===seed));
 const final=result.items.filter(item=>item.type==='agentMessage'&&item.phase==='final_answer').map(item=>item.text).join('\n');assert(final.includes('中文')&&final.includes('结论')&&final.includes('依据'));
 assert(!result.items.some(item=>item.tool==='record_analysis_memory'||item.tool==='query_database'));
 await page.screenshot({path:out+'/flash-cross-session-history.png'});checks.push({name:'真实Flash新会话按需查阅原生提取的旧会话总结',passed:true,threadId:await page.evaluate(()=>state.thread.id),model:result.settings.model,final});
 const state=await api({operation:'state'});checks.push({name:'原生全局合并状态如实报告',passed:true,nativePipeline:state.nativePipeline,nativeControl:state.nativeControl,scheduler:state.scheduler,notice:'历史提取已经完成；未强制清除六小时全局合并冷却。'});
}catch(error){checks.push({name:'原生历史与跨会话回归',passed:false,error:error.stack});process.exitCode=1;await page.screenshot({path:out+'/failure.png'}).catch(()=>{});}
finally{fs.writeFileSync(out+'/results.json',JSON.stringify({scope:'Real Flash/naturally aged native extraction, no timestamp or memory DB edits; isolated service/profile only.',checks,errors},null,2));await browser.close();if(errors.length)process.exitCode=1;console.log(JSON.stringify({checks:checks.map(c=>({name:c.name,passed:c.passed})),errors}));}
